/*
# Seed demo content wave 2 (entries)

1. Purpose
- Adds 24 realistic published entries (4 per vertical) so the homepage, vertical feeds,
  search, and entry detail pages look rich and complete.
- Entries are matched to existing categories by (vertical_id, slug) so no hardcoded IDs.
- Idempotent: guarded by NOT EXISTS on (vertical_id, slug), so re-running adds nothing.
2. Tables modified
- `entries`: insert only, no updates or deletes.
3. Security
- No policy changes; entries keep existing RLS.
*/

INSERT INTO entries (vertical_id, category_id, slug, title, summary, content, status, published_at, metadata)
SELECT v.id, c.id, d.slug, d.title, d.summary, d.content, 'published', now() - (d.days_ago || ' days')::interval, '{}'::jsonb
FROM (VALUES
  ('informational', 'tips-tricks', 'lowering-your-energy-bill-in-winter', 'Lowering Your Energy Bill in Winter', 'Ten low-cost habits that trim heating costs without sacrificing comfort.', 'Heating dominates winter utility bills. Start with a programmable thermostat set to 68F while home and 60F overnight. Seal drafty windows with weatherstripping, open curtains on south-facing walls during the day, and close them at dusk. Reverse ceiling fans clockwise to push warm air down. Maintain your furnace: a clogged filter can raise heating costs by up to 15 percent. Finally, compare your usage against last year on the utility dashboard to catch leaks early.', 6),
  ('informational', 'explainers', 'how-public-key-encryption-works', 'How Public-Key Encryption Works', 'The two-key system behind HTTPS, signed emails, and secure messaging explained simply.', 'Public-key cryptography gives every participant a key pair: a public key anyone can use to encrypt messages to you, and a private key only you hold to decrypt them. When you visit an HTTPS site, your browser uses the server''s public key to agree on a shared session secret; the actual page data then flows through fast symmetric encryption. The same pair, used in reverse, produces digital signatures: only the private key can sign, and anyone with the public key can verify.', 12),
  ('informational', 'how-to-guides', 'filing-your-first-tax-return', 'Filing Your First Tax Return', 'A step-by-step guide for first-time filers: documents, forms, and common pitfalls.', 'Gather your income documents first: W-2s from employers and 1099s from freelance or interest income. Choose your filing status, decide whether the standard deduction or itemizing saves more, and claim education credits if you paid tuition. Free filing options exist through the IRS Free File program for most first-time filers. Double-check bank routing numbers for your refund, keep a copy of the return, and file early to reduce the risk of refund fraud.', 20),
  ('informational', 'tips-tricks', 'speed-up-an-old-laptop', 'Speed Up an Old Laptop', 'Practical upgrades and cleanup steps that make a five-year-old laptop feel new again.', 'Before buying anything, uninstall startup bloat and check what launches at boot. Replace a spinning hard drive with an SSD: this single change typically doubles perceived speed. Add RAM if the machine accepts it; 8 GB is the practical floor for modern browsers. On Windows, disable visual effects; on Linux, try a lighter desktop environment. Repaste the CPU if thermals throttle under load, and keep vents dust-free.', 30),
  ('reference', 'glossaries', 'statistics-terms-glossary', 'Statistics Terms: A Glossary', 'From p-value to standard deviation: the vocabulary of statistics in plain language.', 'Mean, median, and mode measure central tendency; variance and standard deviation measure spread. A p-value is the probability of seeing data at least this extreme if the null hypothesis were true — not the probability the hypothesis is false. Confidence intervals give a range of plausible parameter values. Correlation describes association between variables; regression models it. Bias is systematic error, while variance is random fluctuation.', 8),
  ('reference', 'conversion-tables', 'cooking-measurement-conversions', 'Cooking Measurement Conversions', 'Cups, tablespoons, grams, and ounces: the kitchen conversion table that covers most recipes.', 'One cup equals 16 tablespoons or about 237 milliliters. A tablespoon is three teaspoons. Butter: one cup is 227 grams. Flour: one cup is roughly 120 grams by weight, which is why baking recipes prefer grams. Oven temperatures convert at 350F = 175C = gas mark 4. Weight conversions are exact while volume-to-weight varies by ingredient density, so weighing ingredients is always more reliable than scooping.', 14),
  ('reference', 'cheat-sheets', 'git-commands-cheat-sheet', 'Git Commands Cheat Sheet', 'The everyday git commands for branching, merging, undoing, and inspecting history.', 'git status shows what changed; git diff shows line-level edits. Create a branch with git switch -c feature-name and publish it with git push -u origin. Merge with git merge or keep history linear with git rebase. Undo gracefully: git restore stages and files, git revert makes a counter-commit, and git reflog rescues lost commits. Inspect history with git log --oneline --graph --all.', 18),
  ('reference', 'glossaries', 'legal-terms-plain-english', 'Legal Terms in Plain English', 'Plaintiff, tort, indemnify: what everyday contract and court vocabulary actually means.', 'A plaintiff sues; a defendant is sued. A tort is a civil wrong, like negligence, distinct from a crime. Indemnify means to compensate for harm or loss. Liability is legal responsibility; cap it with a limitation-of-liability clause. Force majeure excuses performance for events beyond control. Jurisdiction is a court''s power to decide a case. Severability keeps the rest of a contract alive when one clause falls.', 26),
  ('educational', 'courses', 'python-basics-course-outline', 'Python Basics: Course Outline', 'A four-week introduction from variables and loops to functions and file handling.', 'Week 1 covers values, variables, and the REPL. Week 2 introduces control flow: if statements, for and while loops, and lists. Week 3 builds functions, arguments, and return values, plus dictionaries for structured data. Week 4 reads and writes files and finishes with a small project, such as a to-do tracker that persists to CSV. Each week pairs two lessons with three graded exercises and a short quiz.', 5),
  ('educational', 'exercises', 'algebra-practice-linear-equations', 'Algebra Practice: Linear Equations', 'Twenty progressively harder linear equation problems with full worked solutions.', 'Start with one-step equations like x + 5 = 12, advance to two-step equations such as 3x - 4 = 11, then tackle variables on both sides. Later problems include fractions and distributing. Full solutions show each step: move constants first, isolate the variable, and check the answer by substitution. A final challenge set applies linear equations to rate and mixture word problems.', 10),
  ('educational', 'lessons', 'periodic-table-lesson', 'The Periodic Table: Lesson', 'How the table is organized, what periods and groups mean, and how to read element tiles.', 'The periodic table orders elements by atomic number, the count of protons. Rows are periods: elements in the same period have the same number of electron shells. Columns are groups: elements in the same group share outer-electron counts and therefore similar chemistry. Alkali metals react violently with water; noble gases barely react at all. Element tiles show the symbol, atomic number, and atomic mass.', 16),
  ('educational', 'lessons', 'cell-division-mitosis-lesson', 'Cell Division: Mitosis Explained', 'The stages of mitosis, why cells divide, and where the process goes wrong in cancer.', 'Mitosis copies a cell''s genome and splits it into two identical daughter cells. Prophase condenses chromosomes; metaphase lines them at the cell''s equator; anaphase pulls sister chromatids apart; telophase re-forms nuclei and cytokinesis divides the cytoplasm. Checkpoints before and during the process catch DNA damage. When checkpoint genes mutate, uncontrolled division — the hallmark of cancer — can begin.', 22),
  ('encyclopedic', 'places', 'sahara-desert', 'Sahara Desert', 'The world''s largest hot desert: geography, climate history, and human adaptation.', 'The Sahara spans 9.2 million square kilometers across North Africa, roughly the size of the United States. Though arid today, rock art and lake sediments record a green Sahara with monsoon rains as recently as 5,000 years ago. Temperatures exceed 50C in summer while nights can approach freezing. Population clusters in oases and along the Nile and Atlantic coast; camel caravan routes historically linked salt mines to river markets.', 4),
  ('encyclopedic', 'events', 'the-apollo-11-mission', 'Apollo 11', 'The 1969 mission that first landed humans on the Moon, from launch to splashdown.', 'Apollo 11 launched on Saturn V from Kennedy Space Center on July 16, 1969. Four days later, the Eagle lunar module touched down in the Sea of Tranquility as fuel ran low. Neil Armstrong and Buzz Aldrin spent 21.5 hours on the surface, collecting 21.5 kilograms of samples, while Michael Collins orbited above. The crew splashed down in the Pacific on July 24 and spent three weeks in quarantine.', 9),
  ('encyclopedic', 'people', 'nikola-tesla-biography', 'Nikola Tesla', 'The inventor and engineer who developed alternating current and pioneered radio control.', 'Nikola Tesla (1856-1943) emigrated from Serbia to America in 1884 and championed alternating current over Edison''s direct current in the "War of the Currents." His polyphase system powered the 1893 Chicago World''s Fair and, via the Adams Plant, lit Buffalo from Niagara Falls. He demonstrated radio-controlled boats in 1898 and patented the Tesla coil. He died in New York, his wireless-power ambitions unrealized but his AC patents foundational.', 15),
  ('encyclopedic', 'places', 'mount-everest', 'Mount Everest', 'Earth''s highest peak: height, geology, climbing history, and environmental pressures.', 'Mount Everest rises 8,849 meters above sea level on the Nepal-China border. The summit rock is marine limestone pushed up as India collided with Asia, a collision that continues and raises the peak a few millimeters yearly. Hillary and Norgay first summited in 1953; more than 6,000 climbers have followed. Overcrowding, fixed ropes, and accumulated waste now drive permit limits and clean-up expeditions.', 24),
  ('catalogs', 'home-garden', 'robot-lawn-mowers-compared', 'Robot Lawn Mowers Compared', 'Boundary-wire and vision-based robot mowers by coverage area, slope rating, and price.', 'Robot mowers fall into two camps: perimeter-wire models and newer vision-based units that map lawns with cameras. Coverage ratings run from 500 square meters for compact models to 5,000 for flagship docks. Slope handling tops out around 45 percent. Expect 55 to 65 decibels, quiet enough for overnight cutting. Anti-theft PIN locks and lift sensors are standard; premium models add GPS tracking.', 7),
  ('catalogs', 'electronics', 'mechanical-keyboard-switches', 'Mechanical Keyboard Switches', 'Linear, tactile, and clicky switches compared by actuation force and travel.', 'Switches define how a keyboard feels. Linear switches press smoothly with constant force, favored for gaming. Tactile switches add a bump at actuation, preferred for typing feedback. Clicky switches add an audible click at the bump. Actuation forces range from 35 to 60 grams; travel distances from 3 to 4 millimeters. Hot-swappable boards let you mix switch types without soldering.', 11),
  ('catalogs', 'tools', 'socket-wrench-sets-buyers-guide', 'Socket Wrench Sets: Buyer''s Guide', 'Drive sizes, tooth counts, and the sockets every starter set should include.', 'Drive sizes define the ratchet: 1/4-inch for small fasteners, 3/8-inch as the general-purpose middle, 1/2-inch for high torque. A 72-tooth ratchet needs a 5-degree swing arc, useful in tight engine bays. Starter sets include 10 to 19 millimeter sockets in both shallow and deep well, extensions, and a universal joint. Chrome-vanadium steel with a full polish resists corrosion in garage humidity.', 17),
  ('catalogs', 'home-garden', 'air-purifier-filter-types', 'Air Purifier Filter Types', 'HEPA, activated carbon, and washable filters compared for rooms up to 500 square feet.', 'True HEPA filters capture 99.97 percent of particles at 0.3 microns: pollen, dust, and smoke. Activated carbon beds adsorb odors and volatile organic compounds, and their mass — measured in pounds — matters more than a thin coated mesh. Washable pre-filters extend main-filter life but are not fine filtration. Room-size ratings assume two air changes per hour; check the clean air delivery rate, not marketing claims.', 21),
  ('scientific', 'datasets', 'global-sea-surface-temperature-dataset', 'Global Sea Surface Temperature Dataset', 'Satellite-derived daily SST grids at 0.05 degrees with bias corrections and QC flags.', 'This dataset provides daily global sea surface temperature on a 0.05-degree grid derived from infrared satellite radiometry, anchored to drifting and moored buoy measurements for bias correction. Files include per-pixel quality flags, ice masks, and a background error field for uncertainty propagation. Records extend from 1981 to the present, with a documented switch from AVHRR to multi-sensor blending in 2007.', 3),
  ('scientific', 'papers', 'attention-is-transformers-paper', 'Attention Is All You Need', 'Summary of the 2017 paper introducing the Transformer architecture behind modern language models.', 'The paper dispensed with recurrence entirely, relying on scaled dot-product self-attention to relate every token pair in a sequence in parallel. Multi-head attention lets different heads attend to different relation types, while positional encodings inject word order. Training on eight GPUs took three and a half days and set new machine-translation records. The architecture — encoder stack, decoder stack, feed-forward blocks — became the template for modern language models.', 13),
  ('scientific', 'technical-summaries', 'li-ion-battery-degradation-summary', 'Lithium-Ion Battery Degradation: Summary', 'Mechanisms of capacity fade in lithium-ion cells and the operating conditions that accelerate them.', 'Capacity fade stems from three mechanisms: growth of the solid-electrolyte interphase consuming cyclable lithium, loss of active cathode material through particle cracking, and lithium plating at low temperatures or high charge rates. Each cycle adds micron-scale damage, but calendar aging often dominates: cells held at full charge degrade faster than cycled ones. Keeping charge between 20 and 80 percent and avoiding heat measurably extends pack life.', 19),
  ('scientific', 'datasets', 'genomic-variant-frequency-database', 'Genomic Variant Frequency Database', 'Population allele frequencies for missense variants across 250,000 genomes.', 'This resource aggregates observed allele frequencies for protein-altering variants across 250,000 genomes, stratified by ancestry group. Each variant row carries depth, quality, and homozygote counts, with frequency confidence intervals. Clinically, the database distinguishes benign polymorphisms from rare variants absent from healthy populations — a key filter for interpreting patient sequencing results.', 28)
) AS d(vertical_slug, category_slug, slug, title, summary, content, days_ago)
JOIN verticals v ON v.slug = d.vertical_slug
JOIN categories c ON c.vertical_id = v.id AND c.slug = d.category_slug
WHERE NOT EXISTS (
  SELECT 1 FROM entries e WHERE e.vertical_id = v.id AND e.slug = d.slug
);